const wm_source_sprite *wm_progress_sprite_find(const char *source_frame) {
    if (!source_frame) return 0;
    for (size_t i=0;i<sizeof(sprites)/sizeof(sprites[0]);++i) if (!strcmp(sprites[i].source_frame, source_frame)) return &sprites[i];
    return 0;
}

size_t wm_progress_sprite_count(void) { return sizeof(sprites)/sizeof(sprites[0]); }

